# -*- coding: utf-8 -*-
# PTX source for a naive batched FP16 GEMM (A: (B,M,K), B: (B,K,N) -> C: (B,M,N))
# Each thread computes one output element C[b, i, j] using a dot‑product over K.
# This kernel is deliberately simple and works on SM80 (A100).

PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

// ---------------------------------------------------------------
// Kernel entry
// ---------------------------------------------------------------
.visible .entry batched_gemm_fp16(
    .param .u64 A_ptr,          // const half * A
    .param .u64 B_ptr,          // const half * B
    .param .u64 C_ptr,          //       half * C
    .param .u32 batch,          // int batch
    .param .u32 M,              // int M
    .param .u32 N,              // int N
    .param .u32 K               // int K
)
{
    // -----------------------------------------------------------
    // Registers
    // -----------------------------------------------------------
    .reg .pred   %p<2>;
    .reg .b32    %r<20>;
    .reg .b64    %rd<20>;
    .reg .f16    %f16a, %f16b;
    .reg .f32    %acc, %fa, %fb;

    // -----------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------
    ld.param.u64    %rd1, [A_ptr];
    ld.param.u64    %rd2, [B_ptr];
    ld.param.u64    %rd3, [C_ptr];
    ld.param.u32    %r1,  [batch];
    ld.param.u32    %r2,  [M];
    ld.param.u32    %r3,  [N];
    ld.param.u32    %r4,  [K];

    // -----------------------------------------------------------
    // Thread/block indices
    //   blockIdx.x : batch index
    //   threadIdx.y : row index (0 .. M-1)
    //   threadIdx.x : col index (0 .. N-1)
    // -----------------------------------------------------------
    mov.u32         %r5, %ctaid.x;        // batch index
    mov.u32         %r6, %tid.y;          // row within output matrix
    mov.u32         %r7, %tid.x;          // col within output matrix

    // -----------------------------------------------------------
    // Guard: if thread is out of bounds, exit
    // -----------------------------------------------------------
    setp.ge.u32     %p0, %r6, %r2;        // row >= M ?
    @%p0 bra        DONE;
    setp.ge.u32     %p0, %r7, %r3;        // col >= N ?
    @%p0 bra        DONE;

    // -----------------------------------------------------------
    // Compute base pointers for this batch
    //   A_batch = A + batch * M * K
    //   B_batch = B + batch * K * N
    //   C_batch = C + batch * M * N
    // -----------------------------------------------------------
    cvt.u64.u32     %rd4, %r5;            // batch as 64‑bit
    mul.lo.u64      %rd5, %rd4, %r2;      // batch * M
    mul.lo.u64      %rd5, %rd5, %r4;      // * K
    mul.lo.u64      %rd5, %rd5, 2;        // * sizeof(half)
    add.u64         %rd6, %rd1, %rd5;     // A_batch

    mul.lo.u64      %rd7, %rd4, %r4;      // batch * K
    mul.lo.u64      %rd7, %rd7, %r3;      // * N
    mul.lo.u64      %rd7, %rd7, 2;
    add.u64         %rd8, %rd2, %rd7;     // B_batch

    mul.lo.u64      %rd9, %rd4, %r2;      // batch * M
    mul.lo.u64      %rd9, %rd9, %r3;      // * N
    mul.lo.u64      %rd9, %rd9, 2;
    add.u64         %rd10, %rd3, %rd9;    // C_batch

    // -----------------------------------------------------------
    // Compute offsets for the first element of the row / column
    // -----------------------------------------------------------
    // offsetA = row * K
    mul.lo.u32      %r8, %r6, %r4;        // row * K
    // offsetB = col (will be added inside the k‑loop)
    // offsetC = row * N + col
    mul.lo.u32      %r9, %r6, %r3;        // row * N
    add.u32         %r9, %r9, %r7;        // row*N + col

    // -----------------------------------------------------------
    // Convert element offsets to byte offsets (half = 2 bytes)
    // -----------------------------------------------------------
    mul.lo.u32      %r8, %r8, 2;          // *2
    mul.lo.u32      %r9, %r9, 2;          // *2

    // -----------------------------------------------------------
    // Pointers to the start of the row of A and the start of the
    // column of B (the column is not contiguous, we will stride)
    // -----------------------------------------------------------
    add.u64         %rd11, %rd6, %r8;     // &A[batch, row, 0]
    add.u64         %rd12, %rd8, %r7;     // &B[batch, 0, col] (col*2 added later)

    // -----------------------------------------------------------
    // Accumulator in FP32
    // -----------------------------------------------------------
    mov.f32         %acc, 0.0;

    // -----------------------------------------------------------
    // Loop over K
    // -----------------------------------------------------------
    mov.u32         %r10, 0;              // k = 0
LOOP_K:
    setp.ge.u32     %p1, %r10, %r4;       // if k >= K break
    @%p1 bra        END_LOOP;

    // Load A[row, k] (half)
    mul.lo.u32      %r11, %r10, 2;        // k * 2 (byte offset)
    add.u64         %rd13, %rd11, %r11;   // &A[row, k]
    ld.global.f16   %f16a, [%rd13];
    cvt.rn.f32.f16  %fa, %f16a;           // convert to FP32

    // Load B[k, col] (half)
    // B is stored row‑major (k dimension is leading)
    mul.lo.u32      %r12, %r10, %r3;      // k * N
    mul.lo.u32      %r12, %r12, 2;        // *2
    add.u32         %r12, %r12, %r7;      // +col
    mul.lo.u32      %r12, %r12, 2;        // *2 (byte offset)
    add.u64         %rd14, %rd8, %r12;    // &B[k, col]
    ld.global.f16   %f16b, [%rd14];
    cvt.rn.f32.f16  %fb, %f16b;           // convert to FP32

    // FMA: acc += fa * fb
    fma.rn.f32      %acc, %fa, %fb, %acc;

    // k++
    add.u32         %r10, %r10, 1;
    bra.uni         LOOP_K;

END_LOOP:
    // -----------------------------------------------------------
    // Store result back to C (as half)
    // -----------------------------------------------------------
    // Convert accumulator to half (round‑to‑nearest‑even)
    cvt.rn.f16.f32  %f16a, %acc;

    add.u64         %rd15, %rd10, %r9;    // &C[batch, row, col]
    st.global.f16   [%rd15], %f16a;

DONE:
    ret;
}
"""

# ---------------------------------------------------------------
# Python wrapper class expected by the harness
# ---------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load PTX module using the harness helper
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A, B):
        """
        Executes the batched FP16 GEMM kernel.
        A: torch.Tensor of shape (B, M, K), dtype=torch.float16, CUDA device
        B: torch.Tensor of shape (B, K, N), dtype=torch.float16, CUDA device
        Returns:
            C: torch.Tensor of shape (B, M, N), dtype=torch.float16, CUDA device
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        batch, M, K = A.shape
        _, K2, N = B.shape
        assert K == K2

        C = torch.empty((batch, M, N), dtype=torch.float16, device=A.device)

        # Launch configuration:
        # One thread block per output element (row, col) per batch:
        # grid.x = batch
        # blockDim = (N_THREADS_X, N_THREADS_Y) where each thread computes one C element.
        # We'll use 16x16 threads per block (covers 256 output positions); threads outside
        # the bounds simply exit early.
        threads_per_block = (16, 16, 1)   # (tx, ty, tz)
        grid = (batch, 1, 1)

        # Prepare kernel arguments (must be 64‑bit pointers / 32‑bit ints)
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            batch,
            M,
            N,
            K,
        ]

        # Launch the kernel via the harness
        ptx_launch(self.module, "batched_gemm_fp16", grid, threads_per_block, args)

        return C
